const event = $input.first().json;
const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(JSON.stringify(event)).digest('hex');
const timestamp = Date.now();
const agent_id = event.agent_id || 'unknown';
const agent_type = event.agent_type || 'specialist';
const anchor_type = event.anchor_type || 'unknown';
const curvature = event.curvature || 0.0;
const topological_sector = event.topological_sector || 'VortexBound';
const reliability = event.reliability || 0.5;
const audit_count = event.audit_count || 0;
const correction_count = event.correction_count || 0;
const inertia_s_on_line = event.inertia_s_on_line || 0.0;
const inertia_s_simple = event.inertia_s_simple || 0.0;
const inertia_s_distinct = event.inertia_s_distinct || 0.0;
const lemma_32_satisfied = event.lemma_32_satisfied || false;
const pq_scheme = event.pq_scheme || 'Falcon512';
const signature = event.signature || '';
const lat = event.lat || 0.0;
const lon = event.lon || 0.0;
return [{ json: { ...event, event_hash: `0x${hash}`, timestamp, agent_id, agent_type, anchor_type, curvature, topological_sector, reliability, audit_count, correction_count, inertia_s_on_line, inertia_s_simple, inertia_s_distinct, lemma_32_satisfied, pq_scheme, signature, lat, lon, witness_status: 'pending' } }];

const response = $input.first().json;
const event = $input.first().json;
if (response.is_anchored) {
  event.witness_status = 'ANCHORED';
  event.block_height = response.block_height;
  event.energy_cost_mj = response.energy_cost_mj;
  event.anchor_type = response.anchor_type || event.anchor_type;
  event.curvature = response.curvature || event.curvature;
  event.topological_sector = response.topological_sector || event.topological_sector;
  event.reliability = response.reliability || event.reliability;
  event.audit_count = response.audit_count || event.audit_count;
  event.correction_count = response.correction_count || event.correction_count;
  event.inertia_s_on_line = response.inertia_s_on_line || event.inertia_s_on_line;
  event.inertia_s_simple = response.inertia_s_simple || event.inertia_s_simple;
  event.inertia_s_distinct = response.inertia_s_distinct || event.inertia_s_distinct;
  event.lemma_32_satisfied = response.lemma_32_satisfied || event.lemma_32_satisfied;
  event.pq_scheme = response.pq_scheme || event.pq_scheme;
  event.signature = response.signature || event.signature;
  event.chord_latency_ms = response.chord_latency_ms || 3.3;
} else {
  event.witness_status = 'REJECTED';
}
return [{ json: event }];
